// slack-adapter (live): section 13 contract over the Slack Web API (bot token).
const i = $input.first().json;
const api = 'https://slack.com/api/';
const withBlocks = (b) => (Array.isArray(i.blocks) && i.blocks.length ? { ...b, blocks: i.blocks } : b);
switch (i.op) {
  case 'post':
    return [{ json: { op: i.op, method: 'POST', url: api + 'chat.postMessage',
      body: withBlocks({ channel: i.channel, text: i.text || '', unfurl_links: false, unfurl_media: false,
        ...(i.thread_ts ? { thread_ts: i.thread_ts } : {}) }) } }];
  case 'react':
    return [{ json: { op: i.op, method: 'POST', url: api + 'reactions.add', body: { channel: i.channel, timestamp: i.ts, name: i.name } } }];
  case 'update':
    return [{ json: { op: i.op, method: 'POST', url: api + 'chat.update', body: withBlocks({ channel: i.channel, ts: i.ts, text: i.text || '' }) } }];
  default:
    return [{ json: { op: i.op, invalid: true } }];
}

// Maps an HTTP status (or a network failure) to the section 13 error kinds.
function fail(kind, message) { return [{ json: { ok: false, error: { kind, message: String(message).slice(0, 300) } } }]; }
function httpFail(res, what) {
  if (!res || res.statusCode === undefined) return fail('unavailable', what + ': ' + JSON.stringify((res && res.error) || res).slice(0, 200));
  const s = res.statusCode;
  const msg = what + ' ' + s + ': ' + JSON.stringify(res.body).slice(0, 200);
  if (s === 429 || s >= 500) return fail('unavailable', msg);
  if (s === 404 || s === 410) return fail('not_found', msg);
  if (s === 409) return fail('conflict', msg);
  if (s === 401 || s === 403) return fail('unavailable', msg);
  return fail('invalid', msg);
}
const ok2xx = (res) => res && res.statusCode >= 200 && res.statusCode < 300;


const req = $('slack:request').first().json;
if (req.invalid) return fail('invalid', 'unknown op ' + JSON.stringify(req.op) + ' for slack');
const res = $input.first().json;
if (!ok2xx(res)) return httpFail(res, req.op);
const b = res.body || {};
if (!b.ok) {
  const e = String(b.error || 'unknown_error');
  if (req.op === 'react' && e === 'already_reacted') return [{ json: { ok: true } }];
  if (['ratelimited', 'service_unavailable', 'fatal_error', 'internal_error', 'request_timeout', 'not_authed', 'invalid_auth', 'account_inactive', 'token_revoked'].includes(e)) return fail('unavailable', req.op + ': ' + e);
  if (['channel_not_found', 'message_not_found', 'thread_not_found', 'not_in_channel'].includes(e)) return fail('not_found', req.op + ': ' + e);
  return fail('invalid', req.op + ': ' + e);
}
if (req.op === 'post') return [{ json: { ok: true, ts: b.ts } }];
return [{ json: { ok: true } }];
